/* Suite ivsc (D-29..D-34, plan 03-07): the IVSC v1 layer-1 parser against project-authored
 * fixtures. ivs_cart_table.inc is generated by cmake/IvsCartTable.cmake from the files listed in
 * data/expected/cart-fixture-files.ids (data/cart/<stem>.json); it lives in the build tree only.
 *
 * One case per fixture record:
 *   positive  the container hex from the fixture. Its trailer and whole_sha256 were computed at
 *             authoring time with `cmake -E sha256sum`, so the parser's digest check meets an
 *             independent value, and the whole-file digest of the test bytes is compared too.
 *   build     a long container assembled here from runs (prefix, entries, words), with the
 *             typed authoring-time trailer appended; the whole-file digest is compared.
 *   patch     the generator's patched copy of a positive base; when the record asks for it,
 *             the last 32 bytes are resealed here with the core SHA-256 so the defect is reached
 *             past the digest check.
 * Each case calls ivs_ivsc_parse on a heap buffer of exactly the container's size (ASan in the
 * dev preset sees any read past it; a zero-length container is passed as NULL) and compares the
 * status, the report (reason, segment index, byte offset) or the view (segments and their data
 * offsets, recomputed here from the counts), and that a refusal leaves the view untouched and an
 * acceptance leaves the report untouched.
 *
 * Code-built cases (listed in data/expected/tests/ivsc.ids with the records):
 *   ivsc.B08-len-over-max      a caller length of 131,257 (and SIZE_MAX) with a 1-byte buffer is
 *                              OVERSIZED before any byte is read (ASan sees a read past the byte).
 *   ivsc.X02-canonical-roundtrip  every accepted record re-encoded here from its view (prefix,
 *                              entries, the words found at the view's data offsets, a trailer
 *                              from the core SHA-256) reproduces the input bytes exactly.
 *   ivsc.X03-bad-args          NULL view, NULL report and NULL bytes with a length are BAD_ARG
 *                              and write nothing; the argument check precedes the length check.
 * Load level (plan 03-11, D-33, D-34): records of kind load (data/cart/ivsc-load.json) name
 * segments whose span-relative addresses the generator resolved from the literal map; the case
 * assembles the container (words (97 i + 13 k + 5) & 0x3FF), seals it with the core SHA-256 and
 * loads it through ivs_machine_load on a fresh instance of the record's profile, in exact-size
 * heap storage, with the full oracle: status, every report detail field, an all-zero image on a
 * refusal, whole-storage memcmp and state digest equality (D-12); an accepted load reports the
 * image, the bus reads every word, and unload returns the never-loaded digest. Code-built:
 *   ivsc.L07-second-load-duplicate  a second cartridge is DUPLICATE_LOAD, the first unchanged.
 *   ivsc.L08-null-args              NULL machine (BAD_HANDLE), NULL bytes with a length (BAD_ARG),
 *                                   both (BAD_ARG: arguments first); the instance unchanged.
 *   ivsc.L09-unload-restores        load then unload gives the never-loaded digest and bytes.
 *   ivsc.L10-two-instances          a cartridge loaded into A leaves B byte-identical and fresh.
 *   ivsc.B07-load-out-of-span       the B07 container (65,536 words, accepted by the parser) is
 *                                   OUT_OF_RANGE at load: it exceeds the 49,152-word span.
 *   ivsc.X01-span-matches-map       every record that must lie in the span does so in the profile
 *                                   registry, and every load record's literal-map span equals the
 *                                   registry span (map drift detector).
 * Family ivsc.fuzz.* (plan 03-08) lives in ivsc_fuzz.c: seeded mutations of the literal positive
 * records, through the interface of ivsc_fuzz.h (the bases are defined here, the canonical
 * re-encoder used by X02 and the fuzz family in ivsc_reencode.c).
 * Test code may use stdio and malloc; the core may not. */
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "common/ivs_sha256.h"
#include "content/ivsc.h"
#include "ivs/ivs.h"
#include "ivs/ivs_machine.h"
#include "ivs_test.h"
#include "machine/machine.h"
#include "ivsc_fuzz.h"
#include "ivsc_table.h"

#include "ivs_cart_table.inc"

static const uint8_t ic_magic[8] = {0x89u, 0x49u, 0x56u, 0x53u, 0x43u, 0x0Du, 0x0Au, 0x1Au};

/* Reason names for diagnostics only (spec reason table order). */
static const char *const ic_reason_names[IVS_IVSC_REASON_COUNT] = {
    "none",           "truncated",      "too-large",      "magic",          "version",
    "flags",          "reserved",       "trailing",       "segment-count",  "size-mismatch",
    "segment-length", "segment-width",  "segment-attr",   "segment-reserved", "addr-wrap",
    "order",          "overlap",        "digest",         "word-range"};

static const char *ic_reason_name(uint32_t r)
{
  return r < IVS_IVSC_REASON_COUNT ? ic_reason_names[r] : "?";
}

static void ic_put16(uint8_t *p, uint32_t v)
{
  p[0] = (uint8_t)((v >> 8) & 0xFFu);
  p[1] = (uint8_t)(v & 0xFFu);
}

static void ic_put32(uint8_t *p, uint32_t v)
{
  p[0] = (uint8_t)((v >> 24) & 0xFFu);
  p[1] = (uint8_t)((v >> 16) & 0xFFu);
  p[2] = (uint8_t)((v >> 8) & 0xFFu);
  p[3] = (uint8_t)(v & 0xFFu);
}

static uint32_t ic_get32(const uint8_t *p)
{
  return ((uint32_t)p[0] << 24) | ((uint32_t)p[1] << 16) | ((uint32_t)p[2] << 8) | (uint32_t)p[3];
}

/* Assemble a build record into a fresh heap buffer of exactly its size. */
static int ic_build(const ivs_cart_fixture *f, uint8_t **out, size_t *out_len)
{
  size_t words = 0u;
  size_t total;
  size_t at;
  size_t i;
  uint8_t *b;
  for (i = 0u; i < f->n_segs; i++) {
    words += f->segs[i].len_words;
  }
  total = IVS_IVSC_PREFIX_BYTES + IVS_IVSC_ENTRY_BYTES * f->n_segs + 2u * words + IVS_IVSC_TRAILER_BYTES;
  b = malloc(total);
  if (b == NULL) {
    return 0;
  }
  memcpy(b, ic_magic, sizeof ic_magic);
  ic_put16(b + 8, 1u);
  ic_put16(b + 10, 0u);
  ic_put32(b + 12, 0u);
  ic_put32(b + 16, (uint32_t)total);
  ic_put16(b + 20, (uint32_t)f->n_segs);
  ic_put16(b + 22, 0u);
  for (i = 0u; i < f->n_segs; i++) {
    uint8_t *e = b + IVS_IVSC_PREFIX_BYTES + IVS_IVSC_ENTRY_BYTES * i;
    ic_put16(e, f->segs[i].addr);
    ic_put16(e + 2, f->segs[i].len_words);
    e[4] = (uint8_t)IVS_IVSC_WIDTH_BITS;
    e[5] = 0u;
    ic_put16(e + 6, 0u);
  }
  at = IVS_IVSC_PREFIX_BYTES + IVS_IVSC_ENTRY_BYTES * f->n_segs;
  for (i = 0u; i < f->n_runs; i++) {
    uint32_t c;
    for (c = 0u; c < f->runs[i].count; c++) {
      ic_put16(b + at, f->runs[i].word);
      at += 2u;
    }
  }
  if (at != total - IVS_IVSC_TRAILER_BYTES) {
    free(b);
    return 0;
  }
  memcpy(b + at, f->trailer, IVS_IVSC_TRAILER_BYTES);
  *out = b;
  *out_len = total;
  return 1;
}

/* The fixture's container in a fresh heap buffer of exactly its size (NULL for 0 bytes). */
static int ic_bytes(const ivs_cart_fixture *f, uint8_t **out, size_t *out_len)
{
  uint8_t *b;
  if (f->kind == IVS_CART_BUILD) {
    return ic_build(f, out, out_len);
  }
  *out = NULL;
  *out_len = f->n_bytes;
  if (f->n_bytes == 0u) {
    return 1;
  }
  b = malloc(f->n_bytes);
  if (b == NULL) {
    return 0;
  }
  memcpy(b, f->bytes, f->n_bytes);
  if (f->reseal) {
    ivs_sha256_digest(b, f->n_bytes - IVS_IVSC_TRAILER_BYTES, b + f->n_bytes - IVS_IVSC_TRAILER_BYTES);
  }
  *out = b;
  return 1;
}

/* An accepted view against the expected segments: header fields, counts, every segment and its
 * data offset (recomputed from the counts), zeroed entries past the count. */
static int ic_check_view(const ivs_cart_fixture *f, const uint8_t *b, size_t len, const ivs_ivsc_view *v)
{
  size_t i;
  size_t words = 0u;
  int ok = 1;
  if (v->version != 1u || v->flags != 0u || v->required_features != ic_get32(b + 12) || v->total_bytes != len ||
      v->segment_count != f->n_segs) {
    ivs_test_diag("view header: version %u flags %u features 0x%08X total %u count %u (want total %zu count %zu)",
                  (unsigned)v->version, (unsigned)v->flags, (unsigned)v->required_features,
                  (unsigned)v->total_bytes, (unsigned)v->segment_count, len, f->n_segs);
    ok = 0;
  }
  for (i = 0u; i < IVS_IVSC_MAX_SEGMENTS; i++) {
    const ivs_ivsc_segment *s = &v->segs[i];
    if (i < f->n_segs) {
      size_t want_off = IVS_IVSC_PREFIX_BYTES + IVS_IVSC_ENTRY_BYTES * f->n_segs + 2u * words;
      if (s->addr != f->segs[i].addr || s->len_words != f->segs[i].len_words || s->data_byte_offset != want_off) {
        ivs_test_diag("segment %zu: got addr %04X len %u data at %u, want %04X len %u data at %zu", i,
                      (unsigned)s->addr, (unsigned)s->len_words, (unsigned)s->data_byte_offset,
                      (unsigned)f->segs[i].addr, (unsigned)f->segs[i].len_words, want_off);
        ok = 0;
      }
      words += f->segs[i].len_words;
    } else if (s->addr != 0u || s->len_words != 0u || s->data_byte_offset != 0u) {
      ivs_test_diag("segment %zu past the count is not zero", i);
      ok = 0;
    }
  }
  /* The whole-file digest of the view (A-04) against the typed authoring-time digest. */
  if (f->whole_sha256 != NULL && memcmp(v->file_sha256, f->whole_sha256, sizeof v->file_sha256) != 0) {
    ivs_test_diag("view file_sha256 differs from the record's whole_sha256");
    ok = 0;
  }
  return ok;
}

static int ic_run_record(const ivs_cart_fixture *f)
{
  uint8_t *b = NULL;
  size_t len = 0u;
  ivs_ivsc_view view;
  ivs_ivsc_view view0;
  ivs_ivsc_report rep;
  ivs_ivsc_report rep0;
  ivs_status st;
  int ok = 1;

  if (!ic_bytes(f, &b, &len)) {
    ivs_test_diag("%s: could not assemble the container", f->id);
    return IVS_TEST_FAIL;
  }
  if (f->whole_sha256 != NULL) {
    uint8_t d[IVS_SHA256_DIGEST_BYTES];
    ivs_sha256_digest(b, len, d);
    if (memcmp(d, f->whole_sha256, sizeof d) != 0) {
      ivs_test_diag("%s: the %zu container bytes do not hash to the typed whole_sha256", f->id, len);
      ok = 0;
    }
  }
  memset(&view, 0xA5, sizeof view);
  view0 = view;
  memset(&rep, 0x5A, sizeof rep);
  rep0 = rep;
  st = ivs_ivsc_parse(b, len, &view, &rep);
  if (st != f->status) {
    ivs_test_diag("%s: status %d, want %d (report reason %s, segment %u, offset %u)", f->id, st, f->status,
                  st != IVS_OK ? ic_reason_name(rep.reason) : "-", st != IVS_OK ? (unsigned)rep.segment_index : 0u,
                  st != IVS_OK ? (unsigned)rep.byte_offset : 0u);
    ok = 0;
  } else if (st == IVS_OK) {
    if (memcmp(&rep, &rep0, sizeof rep) != 0) {
      ivs_test_diag("%s: an acceptance wrote the report", f->id);
      ok = 0;
    }
    if (!ic_check_view(f, b, len, &view)) {
      ok = 0;
    }
  } else {
    if (memcmp(&view, &view0, sizeof view) != 0) {
      ivs_test_diag("%s: a refusal wrote the view", f->id);
      ok = 0;
    }
    if (rep.reason != f->reason || (f->has_seg && rep.segment_index != f->seg) ||
        (f->has_off && rep.byte_offset != f->off)) {
      ivs_test_diag("%s: report reason %s segment %u offset %u, want %s segment %s%u offset %s%u", f->id,
                    ic_reason_name(rep.reason), (unsigned)rep.segment_index, (unsigned)rep.byte_offset,
                    ic_reason_name(f->reason), f->has_seg ? "" : "(any) ", (unsigned)f->seg,
                    f->has_off ? "" : "(any) ", (unsigned)f->off);
      ok = 0;
    }
  }
  free(b);
  if (!ok && f->base != NULL) {
    ivs_test_diag("%s: patched from %s%s", f->id, f->base, f->reseal ? ", resealed" : "");
  }
  return ok ? IVS_TEST_PASS : IVS_TEST_FAIL;
}

/* ivsc.B08: an oversize caller length is refused before any byte is read. */
static int ic_b08_len_over_max(void)
{
  static const size_t lens[] = {(size_t)IVS_IVSC_MAX_BYTES + 1u, (size_t)-1};
  uint8_t *b = malloc(1u);
  size_t i;
  int ok = 1;
  if (b == NULL) {
    return IVS_TEST_FAIL;
  }
  b[0] = ic_magic[0];
  for (i = 0u; i < sizeof lens / sizeof lens[0]; i++) {
    ivs_ivsc_view view;
    ivs_ivsc_view view0;
    ivs_ivsc_report rep;
    ivs_status st;
    memset(&view, 0xA5, sizeof view);
    view0 = view;
    memset(&rep, 0x5A, sizeof rep);
    st = ivs_ivsc_parse(b, lens[i], &view, &rep);
    if (st != IVS_E_OVERSIZED || rep.reason != IVS_IVSC_R_TOO_LARGE || rep.segment_index != IVS_IVSC_NO_SEGMENT ||
        rep.byte_offset != IVS_IVSC_MAX_BYTES || rep.required_features != 0u ||
        memcmp(&view, &view0, sizeof view) != 0) {
      ivs_test_diag("length %zu: status %d reason %s segment %u offset %u", lens[i], st, ic_reason_name(rep.reason),
                    (unsigned)rep.segment_index, (unsigned)rep.byte_offset);
      ok = 0;
    }
  }
  free(b);
  return ok ? IVS_TEST_PASS : IVS_TEST_FAIL;
}

/* ivsc.X02: every accepted record round-trips through its view. */
static int ic_x02_canonical_roundtrip(void)
{
  size_t i;
  size_t accepted = 0u;
  size_t want = 0u;
  int ok = 1;
  for (i = 0u; i < ivs_cart_count; i++) {
    const ivs_cart_fixture *f = &ivs_cart_table[i];
    uint8_t *b = NULL;
    size_t len = 0u;
    ivs_ivsc_view view;
    ivs_ivsc_report rep;
    if (f->status != IVS_OK || f->kind == IVS_CART_LOAD) {
      continue;
    }
    want++;
    if (!ic_bytes(f, &b, &len)) {
      ivs_test_diag("%s: could not assemble the container", f->id);
      ok = 0;
      continue;
    }
    if (ivs_ivsc_parse(b, len, &view, &rep) != IVS_OK) {
      ivs_test_diag("%s: not accepted (reason %s)", f->id, ic_reason_name(rep.reason));
      ok = 0;
    } else if (!ivsc_test_reencode_equal(b, len, &view)) {
      ivs_test_diag("%s: the re-encoded view differs from the input", f->id);
      ok = 0;
    } else {
      accepted++;
    }
    free(b);
  }
  if (want == 0u || accepted != want) {
    ivs_test_diag("round trips: %zu of %zu accepted records", accepted, want);
    ok = 0;
  }
  return ok ? IVS_TEST_PASS : IVS_TEST_FAIL;
}

/* The fuzz bases: accepted positive records whose container is literal hex. */
static int ic_is_base(const ivs_cart_fixture *f)
{
  return f->kind == IVS_CART_POSITIVE && f->status == IVS_OK && f->bytes != NULL &&
         f->n_bytes >= IVS_IVSC_MIN_BYTES;
}

size_t ivsc_test_base_count(void)
{
  size_t i;
  size_t n = 0u;
  for (i = 0u; i < ivs_cart_count; i++) {
    n += ic_is_base(&ivs_cart_table[i]) ? 1u : 0u;
  }
  return n;
}

int ivsc_test_base(size_t k, const uint8_t **bytes, size_t *len)
{
  size_t i;
  for (i = 0u; i < ivs_cart_count; i++) {
    if (ic_is_base(&ivs_cart_table[i]) && k-- == 0u) {
      *bytes = ivs_cart_table[i].bytes;
      *len = ivs_cart_table[i].n_bytes;
      return 1;
    }
  }
  return 0;
}

/* ivsc.X03: argument refusals write nothing, and precede the length check. */
static int ic_x03_bad_args(void)
{
  const ivs_cart_fixture *f = NULL;
  ivs_ivsc_view view;
  ivs_ivsc_view view0;
  ivs_ivsc_report rep;
  ivs_ivsc_report rep0;
  size_t i;
  int ok = 1;
  for (i = 0u; i < ivs_cart_count; i++) {
    if (strcmp(ivs_cart_table[i].id, "ivsc.P01-min") == 0) {
      f = &ivs_cart_table[i];
    }
  }
  if (f == NULL || f->bytes == NULL) {
    ivs_test_diag("record ivsc.P01-min is missing");
    return IVS_TEST_FAIL;
  }
  memset(&view, 0xA5, sizeof view);
  view0 = view;
  memset(&rep, 0x5A, sizeof rep);
  rep0 = rep;
  if (ivs_ivsc_parse(f->bytes, f->n_bytes, NULL, &rep) != IVS_E_BAD_ARG || memcmp(&rep, &rep0, sizeof rep) != 0) {
    ivs_test_diag("NULL view");
    ok = 0;
  }
  if (ivs_ivsc_parse(f->bytes, f->n_bytes, &view, NULL) != IVS_E_BAD_ARG || memcmp(&view, &view0, sizeof view) != 0) {
    ivs_test_diag("NULL report");
    ok = 0;
  }
  if (ivs_ivsc_parse(NULL, f->n_bytes, &view, &rep) != IVS_E_BAD_ARG || memcmp(&view, &view0, sizeof view) != 0 ||
      memcmp(&rep, &rep0, sizeof rep) != 0) {
    ivs_test_diag("NULL bytes with a length");
    ok = 0;
  }
  if (ivs_ivsc_parse(NULL, (size_t)IVS_IVSC_MAX_BYTES + 1u, &view, &rep) != IVS_E_BAD_ARG ||
      memcmp(&view, &view0, sizeof view) != 0 || memcmp(&rep, &rep0, sizeof rep) != 0) {
    ivs_test_diag("NULL bytes with an oversize length");
    ok = 0;
  }
  if (ivs_ivsc_parse(f->bytes, f->n_bytes, &view, &rep) != IVS_OK || memcmp(&rep, &rep0, sizeof rep) != 0) {
    ivs_test_diag("the same bytes with valid arguments are not accepted");
    ok = 0;
  }
  return ok ? IVS_TEST_PASS : IVS_TEST_FAIL;
}

/* ---- load level (plan 03-11) ---- */

/* One instance of a profile in exact-size heap storage. */
typedef struct ic_inst {
  uint8_t *storage;
  ivs_machine *m;
} ic_inst;

static int ic_new(ic_inst *x, const char *profile)
{
  ivs_create_options o;
  memset(&o, 0, sizeof o);
  o.struct_size = (uint32_t)sizeof o;
  o.profile_id = profile;
  x->m = NULL;
  x->storage = aligned_alloc(IVS_MACHINE_ALIGN, IVS_MACHINE_BYTES);
  if (x->storage == NULL) {
    return 0;
  }
  memset(x->storage, 0xA5, IVS_MACHINE_BYTES);
  if (ivs_machine_create(&o, x->storage, IVS_MACHINE_BYTES, &x->m) != IVS_OK) {
    free(x->storage);
    x->storage = NULL;
    return 0;
  }
  return 1;
}

static void ic_free(ic_inst *x)
{
  free(x->storage);
  x->storage = NULL;
  x->m = NULL;
}

static uint16_t ic_load_word(uint32_t seg, uint32_t k)
{
  return (uint16_t)((97u * seg + 13u * k + 5u) & 0x3FFu);
}

/* A load record's container: prefix, entries, generated words, core SHA-256 trailer. */
static uint8_t *ic_load_build(const ivs_cart_fixture *f, size_t *out_len)
{
  size_t words = 0u;
  size_t total;
  size_t at;
  size_t i;
  uint32_t k;
  uint8_t *b;
  for (i = 0u; i < f->n_segs; i++) {
    words += f->segs[i].len_words;
  }
  total = IVS_IVSC_PREFIX_BYTES + IVS_IVSC_ENTRY_BYTES * f->n_segs + 2u * words + IVS_IVSC_TRAILER_BYTES;
  b = malloc(total);
  if (b == NULL) {
    return NULL;
  }
  memset(b, 0, total);
  memcpy(b, ic_magic, sizeof ic_magic);
  ic_put16(b + 8, 1u);
  ic_put32(b + 12, f->features);
  ic_put32(b + 16, (uint32_t)total);
  ic_put16(b + 20, (uint32_t)f->n_segs);
  at = IVS_IVSC_PREFIX_BYTES + IVS_IVSC_ENTRY_BYTES * f->n_segs;
  for (i = 0u; i < f->n_segs; i++) {
    uint8_t *e = b + IVS_IVSC_PREFIX_BYTES + IVS_IVSC_ENTRY_BYTES * i;
    ic_put16(e, f->segs[i].addr);
    ic_put16(e + 2, f->segs[i].len_words);
    e[4] = (uint8_t)IVS_IVSC_WIDTH_BITS;
    for (k = 0u; k < f->segs[i].len_words; k++) {
      ic_put16(b + at, ic_load_word((uint32_t)i, k));
      at += 2u;
    }
  }
  ivs_sha256_digest(b, total - IVS_IVSC_TRAILER_BYTES, b + total - IVS_IVSC_TRAILER_BYTES);
  *out_len = total;
  return b;
}

static ivs_load_report ic_poisoned_report(void)
{
  ivs_load_report r;
  memset(&r, 0xA5, sizeof r);
  r.struct_size = (uint32_t)sizeof r;
  return r;
}

static uint16_t ic_bus(const ic_inst *x, uint16_t addr)
{
  return ivs_memsys_read(&((const struct ivs_machine *)(const void *)x->m)->mem, addr);
}

/* A refused load: status, detail, zero image, every instance byte and the digest unchanged. */
static int ic_refused(ic_inst *x, const uint8_t *b, size_t len, ivs_status want, uint32_t reason, uint32_t seg,
                      uint64_t off, uint32_t missing, const char *what)
{
  static const uint8_t zero[sizeof(ivs_image_report)] = {0};
  ivs_load_report r = ic_poisoned_report();
  uint8_t d0[32];
  uint8_t d1[32];
  uint8_t *snap = malloc(IVS_MACHINE_BYTES);
  ivs_status st;
  int ok = 1;
  if (snap == NULL || ivs_machine_state_digest(x->m, IVS_DIGEST_COMPOSITE, d0) != IVS_OK) {
    free(snap);
    return 0;
  }
  memcpy(snap, x->storage, IVS_MACHINE_BYTES);
  st = ivs_machine_load(x->m, IVS_KIND_CARTRIDGE, b, len, NULL, &r);
  if (st != want || r.struct_size != (uint32_t)sizeof r || r.reason != reason || r.segment_index != seg ||
      r.byte_offset != off || r.missing_features != missing) {
    ivs_test_diag("%s: status %d reason %u segment %u offset %llu missing 0x%X, want %d %u %u %llu 0x%X", what, st,
                  (unsigned)r.reason, (unsigned)r.segment_index, (unsigned long long)r.byte_offset,
                  (unsigned)r.missing_features, want, (unsigned)reason, (unsigned)seg, (unsigned long long)off,
                  (unsigned)missing);
    ok = 0;
  } else if (memcmp(&r.image, zero, sizeof zero) != 0) {
    ivs_test_diag("%s: a refused report carries an image", what);
    ok = 0;
  } else if (memcmp(snap, x->storage, IVS_MACHINE_BYTES) != 0) {
    ivs_test_diag("%s: the refused load changed the instance", what);
    ok = 0;
  } else if (ivs_machine_state_digest(x->m, IVS_DIGEST_COMPOSITE, d1) != IVS_OK || memcmp(d0, d1, 32u) != 0) {
    ivs_test_diag("%s: the state digest changed", what);
    ok = 0;
  }
  free(snap);
  return ok;
}

/* An accepted load: the report, every word on the bus, and unload back to the fresh digest. */
static int ic_accepted(ic_inst *x, const ivs_cart_fixture *f, const uint8_t *b, size_t len)
{
  ivs_load_report r = ic_poisoned_report();
  uint8_t d0[32];
  uint8_t d1[32];
  uint8_t sha[32];
  uint32_t units = 0u;
  size_t i;
  uint32_t k;
  ivs_status st;
  if (ivs_machine_state_digest(x->m, IVS_DIGEST_COMPOSITE, d0) != IVS_OK) {
    return 0;
  }
  for (i = 0u; i < f->n_segs; i++) {
    units += f->segs[i].len_words;
  }
  ivs_sha256_digest(b, len, sha);
  st = ivs_machine_load(x->m, IVS_KIND_CARTRIDGE, b, len, NULL, &r);
  if (st != IVS_OK) {
    ivs_test_diag("%s: refused (status %d reason %u)", f->id, st, (unsigned)r.reason);
    return 0;
  }
  if (r.reason != IVS_REASON_NONE || r.segment_index != IVS_SEGMENT_NONE || r.byte_offset != 0u ||
      r.missing_features != 0u || r.image.loaded != 1u || r.image.kind != IVS_KIND_CARTRIDGE ||
      r.image.length_bytes != (uint32_t)len || r.image.length_units != units || r.image.unit_bits != 10u ||
      r.image.base_addr != f->segs[0].addr || memcmp(r.image.sha256, sha, 32u) != 0) {
    ivs_test_diag("%s: report wrong", f->id);
    return 0;
  }
  for (i = 0u; i < f->n_segs; i++) {
    for (k = 0u; k < f->segs[i].len_words; k++) {
      uint16_t a = (uint16_t)(f->segs[i].addr + k);
      if (ic_bus(x, a) != ic_load_word((uint32_t)i, k)) {
        ivs_test_diag("%s: bus reads %04X at $%04X", f->id, (unsigned)ic_bus(x, a), (unsigned)a);
        return 0;
      }
    }
  }
  if (ivs_machine_unload(x->m, IVS_KIND_CARTRIDGE) != IVS_OK ||
      ivs_machine_state_digest(x->m, IVS_DIGEST_COMPOSITE, d1) != IVS_OK || memcmp(d0, d1, 32u) != 0) {
    ivs_test_diag("%s: unload did not restore the never-loaded digest", f->id);
    return 0;
  }
  return 1;
}

static int ic_run_load(const ivs_cart_fixture *f)
{
  ic_inst x;
  size_t len = 0u;
  int ok;
  uint8_t *b = ic_load_build(f, &len);
  if (b == NULL) {
    return IVS_TEST_FAIL;
  }
  if (!ic_new(&x, f->profile)) {
    ivs_test_diag("%s: no instance of profile %s", f->id, f->profile);
    free(b);
    return IVS_TEST_FAIL;
  }
  if (f->status == IVS_OK) {
    ok = ic_accepted(&x, f, b, len);
  } else {
    ok = ic_refused(&x, b, len, f->status, f->reason, f->has_seg ? f->seg : IVS_SEGMENT_NONE,
                    f->has_off ? f->off : 0u, f->missing, f->id);
  }
  ic_free(&x);
  free(b);
  return ok ? IVS_TEST_PASS : IVS_TEST_FAIL;
}

/* A literal fixture container in a fresh heap buffer. */
static uint8_t *ic_fixture_bytes(const char *id, size_t *len)
{
  size_t i;
  for (i = 0u; i < ivs_cart_count; i++) {
    const ivs_cart_fixture *f = &ivs_cart_table[i];
    if (strcmp(f->id, id) == 0) {
      uint8_t *b = NULL;
      if (f->kind == IVS_CART_LOAD || !ic_bytes(f, &b, len)) {
        return NULL;
      }
      return b;
    }
  }
  return NULL;
}

#define IC_PROFILE "intv-2609-ntsc-family-p1"

/* ivsc.L07: a second cartridge is DUPLICATE_LOAD and the first stays (slot report and bytes). */
static int ic_l07_second_load(void)
{
  ic_inst x;
  size_t n1 = 0u;
  size_t n2 = 0u;
  ivs_info info;
  int ok = 0;
  uint8_t *p1 = ic_fixture_bytes("ivsc.P01-min", &n1);
  uint8_t *p2 = ic_fixture_bytes("ivsc.P02-two-segments", &n2);
  uint8_t sha1[32];
  if (p1 == NULL || p2 == NULL || !ic_new(&x, IC_PROFILE)) {
    free(p1);
    free(p2);
    return IVS_TEST_FAIL;
  }
  ivs_sha256_digest(p1, n1, sha1);
  memset(&info, 0, sizeof info);
  info.struct_size = (uint32_t)sizeof info;
  if (ivs_machine_load(x.m, IVS_KIND_CARTRIDGE, p1, n1, NULL, NULL) != IVS_OK) {
    ivs_test_diag("first load refused");
  } else if (ic_refused(&x, p2, n2, IVS_E_DUPLICATE_LOAD, IVS_REASON_SLOT_OCCUPIED, IVS_SEGMENT_NONE, 0u, 0u,
                        "second load")) {
    ok = ivs_machine_info(x.m, &info) == IVS_OK && info.slots[2].loaded == 1u &&
         info.slots[2].length_bytes == (uint32_t)n1 && memcmp(info.slots[2].sha256, sha1, 32u) == 0;
    if (!ok) {
      ivs_test_diag("the first cartridge's slot report changed");
    }
  }
  ic_free(&x);
  free(p1);
  free(p2);
  return ok ? IVS_TEST_PASS : IVS_TEST_FAIL;
}

/* ivsc.L08: NULL machine, NULL bytes with a length, and both; the live instance is unchanged. */
static int ic_l08_null_args(void)
{
  ic_inst x;
  size_t n = 0u;
  ivs_load_report r = ic_poisoned_report();
  int ok = 0;
  uint8_t *p1 = ic_fixture_bytes("ivsc.P01-min", &n);
  if (p1 == NULL || !ic_new(&x, IC_PROFILE)) {
    free(p1);
    return IVS_TEST_FAIL;
  }
  if (ivs_machine_load(NULL, IVS_KIND_CARTRIDGE, p1, n, NULL, &r) != IVS_E_BAD_HANDLE ||
      r.reason != IVS_REASON_HANDLE) {
    ivs_test_diag("NULL machine: status or reason %u wrong", (unsigned)r.reason);
  } else if (!ic_refused(&x, NULL, n, IVS_E_BAD_ARG, IVS_REASON_ARG_NULL_BYTES, IVS_SEGMENT_NONE, 0u, 0u,
                         "NULL bytes")) {
    ivs_test_diag("NULL bytes with a length");
  } else if (ivs_machine_load(NULL, IVS_KIND_CARTRIDGE, NULL, n, NULL, &r) != IVS_E_BAD_ARG ||
             r.reason != IVS_REASON_ARG_NULL_BYTES) {
    ivs_test_diag("NULL machine and NULL bytes: not BAD_ARG (reason %u)", (unsigned)r.reason);
  } else {
    ok = 1;
  }
  ic_free(&x);
  free(p1);
  return ok ? IVS_TEST_PASS : IVS_TEST_FAIL;
}

/* ivsc.L09: load then unload gives the never-loaded digest and instance bytes. */
static int ic_l09_unload_restores(void)
{
  ic_inst x;
  ic_inst fresh;
  size_t n = 0u;
  uint8_t d0[32];
  uint8_t d1[32];
  int ok = 0;
  uint8_t *p2 = ic_fixture_bytes("ivsc.P02-two-segments", &n);
  if (p2 == NULL || !ic_new(&x, IC_PROFILE)) {
    free(p2);
    return IVS_TEST_FAIL;
  }
  if (!ic_new(&fresh, IC_PROFILE)) {
    ic_free(&x);
    free(p2);
    return IVS_TEST_FAIL;
  }
  if (ivs_machine_state_digest(x.m, IVS_DIGEST_COMPOSITE, d0) == IVS_OK &&
      ivs_machine_load(x.m, IVS_KIND_CARTRIDGE, p2, n, NULL, NULL) == IVS_OK &&
      ivs_machine_unload(x.m, IVS_KIND_CARTRIDGE) == IVS_OK &&
      ivs_machine_state_digest(x.m, IVS_DIGEST_COMPOSITE, d1) == IVS_OK) {
    ok = memcmp(d0, d1, 32u) == 0 && memcmp(x.storage, fresh.storage, IVS_MACHINE_BYTES) == 0;
  }
  if (!ok) {
    ivs_test_diag("unload did not restore the never-loaded state");
  }
  ic_free(&fresh);
  ic_free(&x);
  free(p2);
  return ok ? IVS_TEST_PASS : IVS_TEST_FAIL;
}

/* ivsc.L10: a cartridge loaded into A is invisible to B (API-01 isolation). */
static int ic_l10_two_instances(void)
{
  ic_inst a;
  ic_inst b;
  size_t n = 0u;
  uint8_t db0[32];
  uint8_t db1[32];
  uint8_t *snap = malloc(IVS_MACHINE_BYTES);
  int ok = 0;
  uint8_t *p2 = ic_fixture_bytes("ivsc.P02-two-segments", &n);
  if (p2 == NULL || snap == NULL || !ic_new(&a, IC_PROFILE)) {
    free(p2);
    free(snap);
    return IVS_TEST_FAIL;
  }
  if (!ic_new(&b, IC_PROFILE)) {
    ic_free(&a);
    free(p2);
    free(snap);
    return IVS_TEST_FAIL;
  }
  memcpy(snap, b.storage, IVS_MACHINE_BYTES);
  if (ivs_machine_state_digest(b.m, IVS_DIGEST_COMPOSITE, db0) == IVS_OK &&
      ivs_machine_load(a.m, IVS_KIND_CARTRIDGE, p2, n, NULL, NULL) == IVS_OK &&
      ivs_machine_state_digest(b.m, IVS_DIGEST_COMPOSITE, db1) == IVS_OK) {
    ok = memcmp(db0, db1, 32u) == 0 && memcmp(snap, b.storage, IVS_MACHINE_BYTES) == 0 &&
         ic_bus(&a, 0x5000u) != ic_bus(&b, 0x5000u) && ic_bus(&b, 0x5000u) == 0xFFFFu;
  }
  if (!ok) {
    ivs_test_diag("instance B saw instance A's cartridge");
  }
  ic_free(&b);
  ic_free(&a);
  free(p2);
  free(snap);
  return ok ? IVS_TEST_PASS : IVS_TEST_FAIL;
}

/* ivsc.B07 at load: 65,536 words parse, but segment 0 at 0000 lies below the span. */
static int ic_b07_load(void)
{
  ic_inst x;
  size_t n = 0u;
  int ok;
  uint8_t *b = ic_fixture_bytes("ivsc.B07-two-segments-64k", &n);
  if (b == NULL || !ic_new(&x, IC_PROFILE)) {
    free(b);
    return IVS_TEST_FAIL;
  }
  ok = ic_refused(&x, b, n, IVS_E_OUT_OF_RANGE, IVS_REASON_OUT_OF_SPAN, 0u, IVS_IVSC_PREFIX_BYTES, 0u,
                  "ivsc.B07-two-segments-64k");
  ic_free(&x);
  free(b);
  return ok ? IVS_TEST_PASS : IVS_TEST_FAIL;
}

/* ivsc.X01: the records' span assumptions against the profile registry. */
static int ic_x01_span(void)
{
  uint32_t np = ivs_profile_count();
  size_t i;
  size_t checked = 0u;
  int ok = 1;
  for (i = 0u; i < ivs_cart_count; i++) {
    const ivs_cart_fixture *f = &ivs_cart_table[i];
    uint32_t p;
    size_t s;
    if (f->kind == IVS_CART_LOAD) {
      uint32_t index = 0u;
      const ivs_profile_desc *d;
      if (ivs_machine_profile_lookup(f->profile, &index) != IVS_OK || (d = ivs_profile_get(index)) == NULL ||
          d->has_cart_span == 0u || d->cart_lo != f->span_lo || d->cart_hi != f->span_hi) {
        ivs_test_diag("%s: the literal map's span %04X-%04X differs from profile %s's registry span", f->id,
                      (unsigned)f->span_lo, (unsigned)f->span_hi, f->profile);
        ok = 0;
      }
    }
    if (!f->in_span) {
      continue;
    }
    for (p = 0u; p < np; p++) {
      const ivs_profile_desc *d = ivs_profile_get(p);
      if (f->kind == IVS_CART_LOAD && strcmp(d->id, f->profile) != 0) {
        continue;
      }
      for (s = 0u; s < f->n_segs; s++) {
        uint32_t lo = f->segs[s].addr;
        uint32_t end = lo + f->segs[s].len_words - 1u;
        if (d->has_cart_span == 0u || lo < d->cart_lo || end > d->cart_hi) {
          ivs_test_diag("%s: segment %zu ($%04X, %u words) leaves profile %s's span", f->id, s, (unsigned)lo,
                        (unsigned)f->segs[s].len_words, d->id);
          ok = 0;
        }
        checked++;
      }
    }
  }
  if (checked == 0u) {
    ivs_test_diag("no in-span record checked");
    ok = 0;
  }
  return ok ? IVS_TEST_PASS : IVS_TEST_FAIL;
}

static const ivs_test_case ic_code_cases[] = {
    {"ivsc.B07-load-out-of-span", ic_b07_load, NULL},
    {"ivsc.B08-len-over-max", ic_b08_len_over_max, NULL},
    {"ivsc.L07-second-load-duplicate", ic_l07_second_load, NULL},
    {"ivsc.L08-null-args", ic_l08_null_args, NULL},
    {"ivsc.L09-unload-restores", ic_l09_unload_restores, NULL},
    {"ivsc.L10-two-instances", ic_l10_two_instances, NULL},
    {"ivsc.X01-span-matches-map", ic_x01_span, NULL},
    {"ivsc.X02-canonical-roundtrip", ic_x02_canonical_roundtrip, NULL},
    {"ivsc.X03-bad-args", ic_x03_bad_args, NULL},
};
#define IC_CODE_CASES (sizeof ic_code_cases / sizeof ic_code_cases[0])

/* Case order: the fixture records, the code-built cases, the fuzz family. */
static const char *ic_case_id(const void *data, size_t i)
{
  (void)data;
  if (i < ivs_cart_count) {
    return ivs_cart_table[i].id;
  }
  i -= ivs_cart_count;
  return i < IC_CODE_CASES ? ic_code_cases[i].id : ivsc_fuzz_case_id(i - IC_CODE_CASES);
}

static int ic_case_run(const void *data, size_t i)
{
  (void)data;
  if (i < ivs_cart_count) {
    return ivs_cart_table[i].kind == IVS_CART_LOAD ? ic_run_load(&ivs_cart_table[i]) : ic_run_record(&ivs_cart_table[i]);
  }
  i -= ivs_cart_count;
  return i < IC_CODE_CASES ? ic_code_cases[i].fn() : ivsc_fuzz_case_run(i - IC_CODE_CASES);
}

int main(int argc, char **argv)
{
  ivs_test_suite suite;
  memset(&suite, 0, sizeof suite);
  suite.name = "ivsc";
  suite.count = ivs_cart_count + IC_CODE_CASES + IVSC_FUZZ_CASES;
  suite.id = ic_case_id;
  suite.run = ic_case_run;
  suite.sources = ivs_cart_sources;
  suite.n_sources = ivs_cart_source_count;
  return ivs_test_main(argc, argv, &suite);
}
